-- British International School, Phuket (BISP): school row, short name and facts from the school's own site.
-- Fees are read from the school's own PDFs, linked from https://www.bisphuket.ac.th/admissions/school-fees/ (checked 2026-11-14):
-- School-Fees-2026-2027.pdf and Little-Ducks-fees-2026-2027.pdf. Generated by a script that checks every row: the three
-- term amounts add up to the annual figure, and each one-off fee is matched against the PDF text. Term instalments are left
-- out (derivable); bank details, phone numbers and emails are left out. The web page's Little Ducks session times differ
-- from the PDF's (14:15 vs 14:00 for a full day), so session end times are not recorded.
-- Programmes are read from https://www.bisphuket.ac.th/inspire-learning/ pages (checked 2026-11-14).
-- News comes from the school's WordPress RSS feed, which carries publication dates.
-- myispp has a verified BISP record, but its fee source is a third-party site (international-schools-database.com),
-- so src/ispp.ts skips it.
-- is_client = 0: not a client of the operator (confirmed by the operator 2026-11-14).
INSERT INTO schools (slug, name, city, city_slug, country, website, news_feed, ispp_school_id, is_client) VALUES
  ('bisp', 'British International School, Phuket', 'Phuket', 'phuket', 'Thailand',
   'https://www.bisphuket.ac.th', 'https://www.bisphuket.ac.th/feed/',
   'partner-thailand-british-international-school-phuket', 0)
ON CONFLICT (slug) DO UPDATE SET website = excluded.website, news_feed = excluded.news_feed, ispp_school_id = excluded.ispp_school_id,
  is_client = excluded.is_client;

-- "BISP" is the school's own short name (fee schedule, news posts). "Little Ducks" is its pre-nursery.
INSERT OR IGNORE INTO entities (school_slug, name, source_url) VALUES
  ('bisp', 'BISP', 'https://www.bisphuket.ac.th'),
  ('bisp', 'Little Ducks', 'https://www.bisphuket.ac.th/admissions/school-fees/');

